## 5. JavaScript (Node.js)

```js
const fs = require('fs');

// 1️⃣  Read entire file into a string, then split into lines
const data = fs.readFileSync('myfile.txt', 'utf8');
const lines = data.split(/\r?\n/);   // handles Windows & Unix line endings

// 2️⃣  Or, stream the file line‑by‑line (good for big files)
const readline = require('readline');
const stream = fs.createReadStream('myfile.txt');

const rl = readline.createInterface({
    input: stream,
    crlfDelay: Infinity
});

rl.on('line', (line) => {
    console.log(line);   // process each line
});
```

