## 6. Go

```go
package main

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    f, err := os.Open("myfile.txt")
    if err != nil {
        panic(err)
    }
    defer f.Close()

    scanner := bufio.NewScanner(f)
    for scanner.Scan() {
        line := scanner.Text() // no trailing newline
        fmt.Println(line)
    }
    if err := scanner.Err(); err != nil {
        panic(err)
    }
}
```

